34 | /**
35 |  * @author OUCHI Koji
36 |  *
37 |  */
38 | public class OverlappingLineExtractor {
39 | 	private static final Logger logger = LoggerFactory.getLogger(OverlappingLineExtractor.class);
40 | 	private static final double EPS = 1e-5;
41 | 
42 | 	private boolean isOverlap(final OriLine line0, final OriLine line1) {
43 | 		var overlapCount = GeomUtil.distinguishLineSegmentsOverlap(
44 | 				line0.p0, line0.p1, line1.p0, line1.p1);
45 | 		if (overlapCount >= 3) {
46 | 			return true;
47 | 		}
48 | 		if (overlapCount == 2) {
49 | 			if (GeomUtil.distance(line0.p0, line1.p0) < GeomUtil.EPS) {
50 | 				return false;
51 | 			} else if (GeomUtil.distance(line0.p0, line1.p1) < GeomUtil.EPS) {
52 | 				return false;
53 | 			} else if (GeomUtil.distance(line0.p1, line1.p0) < GeomUtil.EPS) {
54 | 				return false;
55 | 			} else if (GeomUtil.distance(line0.p1, line1.p1) < GeomUtil.EPS) {
56 | 				return false;
57 | 			} else {
58 | 				return true;
59 | 			}
60 | 		}
61 | 
62 | 		return false;
63 | 	}
64 | 
65 | 	/**
66 | 	 * extracts all possible overlapping lines.
67 | 	 *
68 | 	 * @param lines
69 | 	 * @return all overlapping lines.
70 | 	 */
71 | 	public Collection<OriLine> extract(final Collection<OriLine> lines) {
72 | 		var watch = new StopWatch(true);
73 | 
74 | 		// make a data structure for fast computation.
75 | 		var hashFactory = new AnalyticLineHashFactory(EPS);
76 | 		var hash = hashFactory.create(lines);
77 | 
78 | 		var overlappingLines = new ConcurrentLinkedDeque<OriLine>();
79 | 
80 | 		// for each angle and intercept, try all pairs of lines and find
81 | 		// overlaps.
82 | 		IntStream.range(0, hash.size()).parallel().forEach(angle_i -> {
83 | 			var byAngle = hash.get(angle_i);
84 | 			IntStream.range(0, byAngle.size()).parallel().forEach(intercept_i -> {
85 | 				var byIntercept = byAngle.get(intercept_i);
86 | 				// for each line
87 | 				IntStream.range(0, byIntercept.size()).parallel().forEach(i -> {
88 | 					var line0 = byIntercept.get(i).getLine();
89 | 					// search another line of overlapping
90 | 					IntStream.range(i + 1, byIntercept.size()).parallel().forEach(j -> {
91 | 						var line1 = byIntercept.get(j).getLine();
92 | 						if (isOverlap(line0, line1)) {
93 | 							overlappingLines.add(line0);
94 | 							overlappingLines.add(line1);
95 | 						}
96 | 					});
97 | 				});
98 | 			});
99 | 		});
100 | 
101 | 		logger.debug("extract(): " + watch.getMilliSec() + "[ms]");
102 | 
103 | 		return overlappingLines;
104 | 	}
105 | 
106 | 	/**
107 | 	 *
108 | 	 * @param lines
109 | 	 * @param target
110 | 	 * @return overlapping lines of {@code target}.
111 | 	 */
112 | 	public Collection<OriLine> extract(final Collection<OriLine> lines, final OriLine target) {
113 | 		return lines.parallelStream()
114 | 				.filter(l -> isOverlap(l, target))
115 | 				.collect(Collectors.toList());
116 | 	}
117 | }
